    for (let c = 0; c < cells[r].length; c++) {
      if (seen[r][c]) continue;
      regions++;
      const stack = [[r, c]];
      while (stack.length) {
        const [y, x] = stack.pop();
        if (!inside(cells, y, x) || seen[y][x] || cells[y][x] !== cells[r][c]) continue;
        seen[y][x] = true;
