  const takeOption = (name, i) => {
    const key = canon(name);
    if (bools.has(key)) {
      set(key, true);
      return i;
    }
    if (isValueToken(argv[i + 1])) {
      set(key, argv[i + 1]);
      return i + 1;
    }
    set(key, true);
    return i;
  };

